fun interface ClickHandler { fun onClick(v: View) }

// Where each fits
view.setOnClick(ClickHandler { it.dismiss() })     // fun interface — named type
view.setAction { it.dismiss() }                    // (View) -> Unit — composable

// Normal interface — lambda NOT allowed:
// interface Listener { fun a() }; view.add(object : Listener { ... })

// The identity trap:
// view.addOnClick { dismiss() }      // instance A
// view.removeOnClick { dismiss() }   // instance B — never matches A!

val handler = ClickHandler { dismiss() }
view.addOnClick(handler)
view.removeOnClick(handler)   // works — same reference

fun foo(a: Int, b: Int = 2) = a + b
// emits: foo(int, int)  +  foo$default(int, int, int, Object)
// foo(1)      -> foo$default(1, 2, 0b10, null)
// foo(1, 9)   -> foo(1, 9)

fun fresh(): MutableList<String> {
    fun rows(n: Int = mutableListOf<String>().size) = n
    return mutableListOf()          // fresh per call when defaulted
}

open class A { open fun f(x: Int = 1) = x }
class B : A() {
    // override fun f(x: Int = 9) = x  // ERROR: overrides can't redeclare defaults
    override fun f(x: Int): Int = x * 2
}

