// Quadratic — plus() copies the whole list each time
var list: List<Int> = emptyList()
repeat(10_000) { i -> list += i }

// Linear — plusAssign() mutates in place
val list2 = mutableListOf<Int>()
repeat(10_000) { i -> list2 += i }

// Operator mapping
class Vec(val x: Int) {
    operator fun plus(o: Vec) = Vec(x + o.x)
    operator fun contains(n: Int) = x == n
}
val v = Vec(1) + Vec(2)     // -> Vec.plus
if (3 in v) {}               // -> Vec.contains

// infix precedence: below arithmetic, above comparison
infix fun Int.xor2(o: Int) = this xor o
val bad = 1 xor2 2 + 3     // 1 xor2 (2+3) = 1 xor2 5 = 4, not (1 xor2 2)+3 = 2

// tailrec — the recursive call is the last statement
fun sum(n: Long, acc: Long = 0): Long =
    if (n == 0L) acc else sum(n - 1, acc + n)   // tail call -> loop

// Not tail-recursive: work after the call
fun depth(tree: Tree?): Int = if (tree == null) 0
    else 1 + maxOf(depth(tree.left), depth(tree.right))  // after-call work

@OptIn(ExperimentalContracts::class)
fun requireName(x: String?) {
    contract { returns() implies (x != null) }
    if (x == null) throw IllegalArgumentException("null")
}

fun greet(x: String?) {
    requireName(x)
    println(x.length)          // smart cast works — thanks to the contract
}

// callsInPlace enables val assignment inside run/with
val answer: Int = run {
    40 + 2                      // EXACTLY_ONCE -> val assignment is legal
}
